+function computeCategoryScores(scoredIssues: ScoredIssue[]): Record<IssueCategory, number> {
+  // Initialize category scores
+  const categoryScores: Record<IssueCategory, number> = {
+    cookies: 100,
+    consentement: 100,
+    documents: 100,
+    securite: 100,
+  };
+
+  // Group issues by category
+  const issuesByCategory: Record<IssueCategory, ScoredIssue[]> = {
+    cookies: [],
+    consentement: [],
+    documents: [],
+    securite: [],
+  };
+
+  for (const scored of scoredIssues) {
+    const issueCode = scored.issue.code;
+    const category = ISSUE_CATEGORY_MAP[issueCode];
+    if (category) {
+      issuesByCategory[category].push(scored);
+    }
+  }
+
+  // Calculate scores per category
+  for (const [category, issues] of Object.entries(issuesByCategory)) {
+    if (issues.length === 0) continue;
+
+    const totalPenalty = issues.reduce((sum, issue) => sum + issue.penalty, 0);
+    let score = Math.max(0, 100 - totalPenalty);
+
+    // If there are critical issues in this category, cap the score
+    const hasCritical = issues.some((issue) => issue.issue.severity === "critical");
+    if (hasCritical) {
+      score = Math.min(score, CRITICAL_SCORE_CAP);
+    }
+
+    categoryScores[category as IssueCategory] = score;
+  }
+
+  return categoryScores;
+}
