--- /dev/null
+++ b/backend/ranks.js
@@ -0,0 +1,40 @@
+// Pure rank mapping (no I/O). Maps a numeric ELO rating to a ranked tier and division.
+const TIER_ORDER = ['Bronze', 'Silver', 'Gold', 'Platinum', 'Diamond', 'Master'];
+
+// Minimum ELO required to enter each tier.
+const TIER_MIN_ELO = [800, 1000, 1200, 1400, 1600, 1800];
+const DIVISION_NAMES = ['IV', 'III', 'II', 'I']; // IV is lowest rank within a tier
+
+function rankForElo(elo) {
+  // Clamp very low ELO to Bronze IV
+  if (elo < TIER_MIN_ELO[0]) elo = TIER_MIN_ELO[0];
+
+  // Check for Master (or above)
+  if (elo >= TIER_MIN_ELO[TIER_MIN_ELO.length - 1]) {
+    return { tier: 'Master', division: null, label: 'Master' };
+  }
+
+  // Find the correct tier
+  let tierIndex = 0;
+  for (let i = TIER_MIN_ELO.length - 2; i >= 0; i--) {
+    if (elo >= TIER_MIN_ELO[i]) {
+      tierIndex = i;
+      break;
+    }
+  }
+
+  const tierName = TIER_ORDER[tierIndex];
+  const tierStart = TIER_MIN_ELO[tierIndex];
+  
+  // Calculate division: 4 (lowest) to 1 (highest) within the tier
+  const division = 4 - Math.floor((elo - tierStart) / 50);
+  const divisionLabel = DIVISION_NAMES[4 - division];
+
+  return {
+    tier: tierName,
+    division: division,
+    label: `${tierName} ${divisionLabel}`
+  };
+}
+
+module.exports = { rankForElo, TIER_ORDER };

