+(function (root) {
+  const PLACEMENT_MATCHES = 5;
+
+  // Resolve ranks module for Node (require) or Browser (globalThis.BlobRanks)
+  let ranks;
+  if (typeof require === 'function') {
+    try { ranks = require('./ranks.js'); } catch (_) {}
+  }
+  if (!ranks && typeof globalThis !== 'undefined' && globalThis.BlobRanks) {
+    ranks = globalThis.BlobRanks;
+  }
+
+  function placementState(rankedGames) {
+    const validCount = typeof rankedGames === 'number' && !isNaN(rankedGames) && rankedGames >= 0;
+    const played = validCount ? Math.floor(rankedGames) : 0;
+    const inPlacement = played < PLACEMENT_MATCHES;
+    return {
+      inPlacement,
+      played,
+      remaining: Math.max(0, PLACEMENT_MATCHES - played),
+      label: `Placement ${played}/${PLACEMENT_MATCHES}`
+    };
+  }
+
+  function displayRank(elo, rankedGames) {
+    const state = placementState(rankedGames);
+    if (state.inPlacement) {
+      return { tier: null, division: null, label: state.label, inPlacement: true };
+    }
+    return { ...ranks.rankForElo(elo), inPlacement: false };
+  }
+
+  const API = { PLACEMENT_MATCHES, placementState, displayRank };
+  if (typeof module !== 'undefined' && module.exports) module.exports = API;
+  else root.BlobPlacement = API;
+})(typeof window !== 'undefined' ? window : globalThis);

